import{_ as a,a0 as o,w as s,s as u,ao as r,I as l,x as t,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux有问必答：Linux 中如何安装 7zip | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：Linux 中如何安装 7zip | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：Linux 中如何安装 7zip | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：Linux 中如何安装 7zip | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141224 Linux FAQs with Answers--How to install 7zip on Linux","title":"Linux有问必答：Linux 中如何安装 7zip","tag":"201501","desc":""},"relativePath":"201501/20141224 Linux FAQs with Answers--How to install 7zip on Linux.md","filePath":"[post].md"}'),z={name:"201501/20141224 Linux FAQs with Answers--How to install 7zip on Linux.md"};function d(x,i,f,m,L,g){const n=o("Link");return s(),u("div",null,[i[14]||(i[14]=r(`<h1 id="linux有问必答-linux-中如何安装-7zip" tabindex="-1">Linux有问必答：Linux 中如何安装 7zip <a class="header-anchor" href="#linux有问必答-linux-中如何安装-7zip" aria-label="Permalink to “Linux有问必答：Linux 中如何安装 7zip”">​</a></h1><blockquote><p><strong>问题</strong>: 我需要要从 ISO 映像中获取某些文件，为此我想要使用 7zip 程序。那么我应该如何安装 7zip 软件呢，[在 Linux 发布版本上完全安装]?</p></blockquote><p>7zip 是一款开源的归档应用程序，开始是为 Windows 系统而开发的。它能对多种格式的档案文件进行打包或解包处理，除了支持其原生的 7z 格式的文档外，还支持包括 XZ、GZIP、TAR、ZIP 和 BZIP2 等这些格式。 通常，7zip 也用来解压 RAR、DEB、RPM 和 ISO 等格式的文件。除了简单的归档功能，7zip 还具有支持 AES-256 算法加密以及自解压和建立多卷存档功能。在支持 POSIX 标准的系统上（Linux、Unix、BSD），原生的 7zip 程序被移植过来并被命名为 p7zip（“POSIX 7zip” 的简称）。</p><p>下面介绍如何在 Linux 中安装 7zip （或 p7zip）。</p><h3 id="在-debian、ubuntu-或-linux-mint-系统中安装-7zip" tabindex="-1">在 Debian、Ubuntu 或 Linux Mint 系统中安装 7zip <a class="header-anchor" href="#在-debian、ubuntu-或-linux-mint-系统中安装-7zip" aria-label="Permalink to “在 Debian、Ubuntu 或 Linux Mint 系统中安装 7zip”">​</a></h3><p>在基于的 Debian 的发布系统中存在有三种 7zip 的软件包。</p><ul><li><strong>p7zip</strong>: 包含 7zr（最小的 7zip 归档工具），仅仅只能处理原生的 7z 格式。</li><li><strong>p7zip-full</strong>: 包含 7z ，支持 7z、LZMA2、XZ、ZIP、CAB、GZIP、BZIP2、ARJ、TAR、CPIO、RPM、ISO 和 DEB 格式。</li><li><strong>p7zip-rar</strong>: 包含一个能解压 RAR 文件的插件。</li></ul><p>建议安装 p7zip-full 包（不是 p7zip），因为这是最完全的 7zip 程序包，它支持很多归档格式。此外，如果您想处理 RAR 文件话，还需要安装 p7zip-rar 包，做成一个独立的插件包的原因是因为 RAR 是一种专有格式。</p><pre><code>$ sudo apt-get install p7zip-full p7zip-rar 
</code></pre><h3 id="在-fedora-或-centos-rhel-系统中安装-7zip" tabindex="-1">在 Fedora 或 CentOS/RHEL 系统中安装 7zip <a class="header-anchor" href="#在-fedora-或-centos-rhel-系统中安装-7zip" aria-label="Permalink to “在 Fedora 或 CentOS/RHEL 系统中安装 7zip”">​</a></h3><p>基于红帽的发布系统上提供了两个 7zip 的软件包。</p><ul><li><strong>p7zip</strong>: 包含 7za 命令，支持 7z、ZIP、GZIP、CAB、ARJ、BZIP2、TAR、CPIO、RPM 和 DEB 格式。</li><li><strong>p7zip-plugins</strong>: 包含 7z 命令，额外的插件，它扩展了 7za 命令（例如支持 ISO 格式的抽取）。</li></ul>`,12)),l("p",null,[i[1]||(i[1]=t("在 CentOS/RHEL 系统中，在运行下面命令前您需要确保 ",-1)),e(n,{href:"http://linux.cn/article-2324-1.html"},{default:p(()=>[...i[0]||(i[0]=[t("EPEL 资源库",-1)])]),_:1}),i[2]||(i[2]=t(" 可用，但在 Fedora 系统中就不需要额外的资源库了。",-1))]),i[15]||(i[15]=r(`<pre><code>$ sudo yum install p7zip p7zip-plugins 
</code></pre><p>注意，跟基于 Debian 的发布系统不同的是，基于红帽的发布系统没有提供 RAR 插件，所以您不能使用 7z 命令来抽取解压 RAR 文件。</p><h3 id="使用-7z-创建或提取归档文件" tabindex="-1">使用 7z 创建或提取归档文件 <a class="header-anchor" href="#使用-7z-创建或提取归档文件" aria-label="Permalink to “使用 7z 创建或提取归档文件”">​</a></h3><p>一旦安装好 7zip 软件后，就可以使用 7z 命令来打包解包各式各样的归档文件了。7z 命令会使用不同的插件来辅助处理对应格式的归档文件。</p><p><img src="https://farm8.staticflickr.com/7583/15874000610_878a85b06a_b.jpg" alt=""></p><p>使用 “a” 选项就可以创建一个归档文件，它可以创建 7z、XZ、GZIP、TAR、 ZIP 和 BZIP2 这几种格式的文件。如果指定的归档文件已经存在的话，它会把文件“附加”到存在的归档中，而不是覆盖原有归档文件。</p><pre><code>$ 7z a &lt;archive-filename&gt; &lt;list-of-files&gt; 
</code></pre><p>使用 “e” 选项可以抽取一个归档文件，抽取出的文件会放在当前目录。抽取支持的格式比创建时支持的格式要多的多，包括 7z、XZ、GZIP、TAR、ZIP、BZIP2、LZMA2、CAB、ARJ、CPIO、RPM、ISO 和 DEB 这些格式。</p><pre><code>$ 7z e &lt;archive-filename&gt;
</code></pre><p>解包的另外一种方式是使用 “x” 选项。和 “e” 选项不同的是，它使用的是全路径来抽取归档的内容。</p><pre><code>$ 7z x &lt;archive-filename&gt;
</code></pre><p>要查看归档的文件列表，使用 “l” 选项。</p><pre><code>$ 7z l &lt;archive-filename&gt;
</code></pre><p>要更新或删除归档文件，分别使用 “u” 和 “d” 选项。</p><pre><code>$ 7z u &lt;archive-filename&gt; &lt;list-of-files-to-update&gt;
$ 7z d &lt;archive-filename&gt; &lt;list-of-files-to-delete&gt;
</code></pre><p>要测试归档的完整性，使用：</p><pre><code>$ 7z t &lt;archive-filename&gt; 
</code></pre><hr>`,18)),l("p",null,[i[4]||(i[4]=t("via:",-1)),e(n,{href:"http://ask.xmodulo.com/install-7zip-linux.html"},{default:p(()=>[...i[3]||(i[3]=[t("http://ask.xmodulo.com/install-7zip-linux.html",-1)])]),_:1})]),l("p",null,[i[7]||(i[7]=t("译者：",-1)),e(n,{href:"https://github.com/runningwater"},{default:p(()=>[...i[5]||(i[5]=[t("runningwater",-1)])]),_:1}),i[8]||(i[8]=t(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...i[6]||(i[6]=[t("wxy",-1)])]),_:1})]),l("p",null,[i[11]||(i[11]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...i[9]||(i[9]=[t("LCTT",-1)])]),_:1}),i[12]||(i[12]=t(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:p(()=>[...i[10]||(i[10]=[t("Linux中国",-1)])]),_:1}),i[13]||(i[13]=t(" 荣誉推出",-1))])])}const I=a(z,[["render",d]]);export{T as __pageData,I as default};
